import React, { useEffect, useState } from 'react';
import { Card } from '../shared';
import { ascpaiAPI } from '../../services/api';

// Theme primitives to match the original layout
const T = {
    bg: "#f8f9fb",
    surface: "#ffffff",
    border: "#e5e7eb",
    borderLight: "#f3f4f6",
    text: "#111827",
    textMid: "#374151",
    textMuted: "#6b7280",
    textFaint: "#9ca3af",
    primary: "#4f46e5",
    primaryLight: "#eef2ff",
    green: "#059669",
    greenLight: "#ecfdf5",
    greenBorder: "#bbf7d0",
    amber: "#d97706",
    amberLight: "#fffbeb",
    amberBorder: "#fde68a",
    red: "#dc2626",
    redLight: "#fef2f2",
    cyan: "#0891b2",
    cyanLight: "#ecfeff",
    greyLight: "#f9fafb",
    greyBorder: "#d1d5db",
    greyDark: "#4b5563",
    shadow: "0 1px 3px rgba(0,0,0,.06), 0 1px 2px rgba(0,0,0,.04)",
};

const REBALANCE_STEPS = [
    { key: 'step_1_spot_provisioning',     label: 'NodePool Updated',     desc: 'Karpenter NodePool patched with target instance types', verifiedKey: 'step_1_verified' },
    { key: 'step_4_new_node_joined',       label: 'New Node Joined',      desc: 'Replacement spot node joined the cluster and is ready', verifiedKey: 'step_4_verified' },
    { key: 'step_2_cordon',               label: 'Node Cordoned',         desc: 'No new pods scheduled on the source node', verifiedKey: 'step_2_verified' },
    { key: 'step_3_draining_pods',        label: 'Pods Drained',          desc: 'Existing pods gracefully evicted to other nodes', verifiedKey: 'step_3_verified' },
    { key: 'step_5_old_node_terminated',  label: 'Old Node Terminated',   desc: 'Source EC2 instance terminated', verifiedKey: 'step_5_verified' },
    { key: 'step_6_optimization_complete',label: 'Complete',              desc: 'Node migration finished', verifiedKey: null },
];

const STEP_CURRENT_MAP = {
    provisioning_spot_pool: 0,
    waiting_for_spot_node: 1,
    cordoning_node: 2,
    draining_pods: 3,
    old_node_terminating: 4,
    old_node_terminating_timeout: 4,
    optimization_complete: 5,
};

const formatCountdown = (seconds) => {
    if (!seconds || seconds <= 0) return '00:00';
    const hrs = Math.floor(seconds / 3600);
    const mins = Math.floor((seconds % 3600) / 60);
    const secs = seconds % 60;
    if (hrs > 0) return `${hrs}:${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
    return `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
};

const RebalancingTimeline = ({ clusterId, actions: externalActions }) => {
    const [actions, setActions] = useState(externalActions || []);
    const [cooldownData, setCooldownData] = useState(null);
    const [nextNodeData, setNextNodeData] = useState(null);
    const [optimizationInProgress, setOptimizationInProgress] = useState(false);
    const [dailyLimitReached, setDailyLimitReached] = useState(false);
    const [dailyLimitInfo, setDailyLimitInfo] = useState({ used: 0, max: 5 });
    const [loading, setLoading] = useState(!externalActions);

    // Absolute timestamps from backend — survive page refresh
    const [cooldownExpiresAt, setCooldownExpiresAt] = useState(null);   // ISO "...Z"
    const [nextCheckAt, setNextCheckAt] = useState(null);               // ISO "...Z"
    // Configured check interval from backend settings (seconds)
    const [checkIntervalSeconds, setCheckIntervalSeconds] = useState(15);
    // Tick counter just to force re-renders every second
    const [, setTick] = useState(0);

    // Compute live seconds from absolute timestamps (stable across page refresh)
    const liveSeconds = cooldownExpiresAt
        ? Math.max(0, Math.floor((new Date(cooldownExpiresAt) - Date.now()) / 1000))
        : 0;
    const nextCycleSeconds = nextCheckAt
        ? Math.max(0, Math.floor((new Date(nextCheckAt) - Date.now()) / 1000))
        : checkIntervalSeconds;

    // Fetch data — always poll rebalancing context; also poll actions independently
    // for faster updates during active migrations (parent may refresh only every 30s)
    useEffect(() => {
        if (!clusterId && !externalActions) return;

        const fetchData = async () => {
            try {
                // Always fetch latest actions independently for live updates
                if (clusterId) {
                    const statusRes = await ascpaiAPI.getRebalancingStatus(clusterId, 10);
                    const freshActions = Array.isArray(statusRes.data) ? statusRes.data : [];
                    setActions(freshActions);
                }

                if (clusterId) {
                    // Fetch unified rebalancing context (cooldown + next target)
                    const ctxRes = await ascpaiAPI.getRebalancingContext(clusterId).catch(() => ({ data: null }));
                    if (ctxRes.data) {
                        const inProg = ctxRes.data.optimization_in_progress || false;
                        setOptimizationInProgress(inProg);
                        const cd = ctxRes.data.cooldown;
                        // Only show cooldown when NOT actively optimizing
                        if (!inProg && cd?.active && cd.expires_at) {
                            setCooldownData(cd);
                            setCooldownExpiresAt(cd.expires_at);
                        } else {
                            setCooldownData(null);
                            setCooldownExpiresAt(null);
                        }
                        // Sync next-check timestamp and configured interval from backend
                        if (ctxRes.data.next_check_at) {
                            setNextCheckAt(ctxRes.data.next_check_at);
                        }
                        if (ctxRes.data.check_interval_seconds) {
                            setCheckIntervalSeconds(ctxRes.data.check_interval_seconds);
                        }
                        setNextNodeData(ctxRes.data.next_target || null);
                        setDailyLimitReached(ctxRes.data.daily_limit_reached || false);
                        setDailyLimitInfo({ used: ctxRes.data.daily_limit_used || 0, max: ctxRes.data.daily_limit_max || 5 });
                    }
                }
            } catch (err) {
                console.error("Failed to fetch rebalancing context:", err);
            } finally {
                setLoading(false);
            }
        };

        fetchData();
        // Poll faster (5s) during active migrations, slower otherwise
        const hasActive = (actions || []).some(a => ['in_progress', 'waiting_agent'].includes(a.status));
        const _pollMs = hasActive ? 5000 : Math.max(10000, checkIntervalSeconds * 500);
        const intervalId = setInterval(fetchData, _pollMs);
        return () => clearInterval(intervalId);
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [clusterId, externalActions, actions.length]);

    // Per-second tick — only triggers re-renders, countdown computed from absolute timestamps
    useEffect(() => {
        const tick = setInterval(() => setTick(t => t + 1), 1000);
        return () => clearInterval(tick);
    }, []);

    // Use independently-fetched actions (more frequent) over parent-provided ones
    const displayActions = actions.length > 0 ? actions : (externalActions || []);

    // Filter to active or recent migrations
    const now = Date.now();
    const visible = (displayActions || []).filter(a => {
        if (['in_progress', 'waiting_agent'].includes(a.status)) return true;
        // Show completed AND failed migrations from the last hour so failures are visible
        if ((a.status === 'completed' || a.status === 'failed') && a.completed_at) {
            return (now - new Date(a.completed_at).getTime()) < 3600_000;
        }
        return false;
    });

    if (loading && !displayActions.length) {
        return <div className="text-center py-4 text-gray-500">Loading timeline data...</div>;
    }

    return (
        <div style={{ marginBottom: 24 }}>
            {/* Real-time Status Metadata Bar */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                {/* Next Node Target */}
                <div style={{ background: T.surface, border: `1px solid ${T.border}`, borderRadius: 8, padding: '12px 16px', display: 'flex', alignItems: 'center', justifyContent: 'space-between', boxShadow: T.shadow }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                        <div style={{ background: T.primaryLight, color: T.primary, width: 32, height: 32, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 16 }}>🎯</div>
                        <div>
                            <div style={{ fontSize: 11, fontWeight: 700, color: T.textFaint, textTransform: 'uppercase', letterSpacing: '0.05em' }}>Next Target</div>
                            <div style={{ fontSize: 14, fontWeight: 600, color: T.text }}>
                                {nextNodeData ? nextNodeData.node : 'Fleet Optimized'}
                            </div>
                        </div>
                    </div>
                    {nextNodeData && (
                        <div style={{ textAlign: 'right' }}>
                            <div style={{ fontSize: 13, fontWeight: 600, color: T.green }}>${nextNodeData.monthly_savings}/mo</div>
                            <div style={{ fontSize: 11, color: T.textMuted }}>Est. Savings</div>
                        </div>
                    )}
                </div>

                {/* Cooldown / In-Progress / Next Cycle Timer */}
                <div style={{
                    background: T.surface,
                    border: `1px solid ${optimizationInProgress ? T.primary : cooldownData && liveSeconds > 0 ? T.amber : dailyLimitReached ? '#f97316' : T.border}`,
                    borderRadius: 8, padding: '12px 16px', boxShadow: T.shadow
                }}>
                    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                            <div style={{
                                background: optimizationInProgress ? T.primaryLight : cooldownData && liveSeconds > 0 ? T.amberLight : dailyLimitReached ? '#fff7ed' : T.greenLight,
                                color: optimizationInProgress ? T.primary : cooldownData && liveSeconds > 0 ? T.amber : dailyLimitReached ? '#f97316' : T.green,
                                width: 32, height: 32, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 16
                            }}>
                                {optimizationInProgress ? '🔄' : cooldownData && liveSeconds > 0 ? '⏳' : dailyLimitReached ? '⚠️' : '✅'}
                            </div>
                            <div>
                                <div style={{ fontSize: 11, fontWeight: 700, color: T.textFaint, textTransform: 'uppercase', letterSpacing: '0.05em' }}>
                                    {optimizationInProgress ? 'Optimization Status' : cooldownData && liveSeconds > 0 ? 'Stabilization Cooldown' : dailyLimitReached ? 'Daily Limit' : 'Stabilization'}
                                </div>
                                <div style={{ fontSize: 14, fontWeight: 600, color: T.text }}>
                                    {optimizationInProgress
                                        ? 'Optimization in progress'
                                        : cooldownData && liveSeconds > 0
                                            ? `${cooldownData.reason === 'post_rebalance' ? 'Post-rebalance' : 'Cluster'} cooldown`
                                            : dailyLimitReached
                                                ? `Daily limit reached`
                                                : 'Ready'}
                                </div>
                            </div>
                        </div>
                        <div style={{ textAlign: 'right' }}>
                            {optimizationInProgress ? (
                                <>
                                    <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                                        <span style={{ width: 8, height: 8, borderRadius: '50%', background: T.primary, display: 'inline-block', animation: 'pulse 1.2s infinite' }} />
                                        <span style={{ fontSize: 13, fontWeight: 700, color: T.primary }}>In Progress</span>
                                    </div>
                                    <div style={{ fontSize: 10, color: T.textMuted }}>Cooldown starts after completion</div>
                                </>
                            ) : dailyLimitReached ? (
                                <>
                                    <div style={{ fontSize: 13, fontWeight: 700, color: '#f97316' }}>{dailyLimitInfo.used}/{dailyLimitInfo.max}</div>
                                    <div style={{ fontSize: 10, color: T.textMuted }}>Resets in 24h · OD nodes bypass limit</div>
                                </>
                            ) : cooldownData && liveSeconds > 0 ? (
                                <>
                                    <div style={{ fontSize: 22, fontWeight: 800, color: T.amber, fontFamily: 'monospace', letterSpacing: '0.05em' }}>
                                        {formatCountdown(liveSeconds)}
                                    </div>
                                    <div style={{ fontSize: 10, color: T.textMuted }}>Stabilization lock (backend)</div>
                                </>
                            ) : (
                                <>
                                    <div style={{ fontSize: 16, fontWeight: 700, color: T.green }}>Ready</div>
                                    <div style={{ fontSize: 10, color: T.textMuted }}>No active cooldown</div>
                                </>
                            )}
                        </div>
                    </div>

                    {/* Bottom row: always show both cooldown remaining + next check countdown */}
                    <div style={{ marginTop: 10, paddingTop: 10, borderTop: `1px solid ${T.borderLight}`, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                        <div style={{ display: 'flex', gap: 20 }}>
                            {cooldownData && liveSeconds > 0 && (
                                <div>
                                    <div style={{ fontSize: 9, fontWeight: 700, color: T.textFaint, textTransform: 'uppercase', letterSpacing: '0.04em', marginBottom: 2 }}>
                                        {cooldownData.reason === 'post_rebalance' ? 'Post-Rebalance Lock' : 'Cluster Cooldown'}
                                    </div>
                                    <div style={{ fontFamily: 'monospace', fontSize: 15, fontWeight: 800, color: T.amber }}>
                                        {formatCountdown(liveSeconds)}
                                    </div>
                                </div>
                            )}
                            <div>
                                <div style={{ fontSize: 9, fontWeight: 700, color: T.textFaint, textTransform: 'uppercase', letterSpacing: '0.04em', marginBottom: 2 }}>
                                    Next Check
                                </div>
                                <div style={{ fontFamily: 'monospace', fontSize: 15, fontWeight: 800, color: nextCycleSeconds <= 3 ? T.primary : T.textMid }}>
                                    {formatCountdown(nextCycleSeconds)}
                                </div>
                            </div>
                        </div>
                        <div style={{ textAlign: 'right' }}>
                            <div style={{ fontSize: 10, color: T.textFaint, fontStyle: 'italic' }}>
                                ⏱ Synced from backend
                            </div>
                            <div style={{ fontSize: 9, color: T.textFaint, marginTop: 1 }}>
                                cycle every {checkIntervalSeconds >= 60
                                    ? `${Math.round(checkIntervalSeconds / 60)}m`
                                    : `${checkIntervalSeconds}s`}
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            <div style={{ fontSize: 13, fontWeight: 700, color: T.text, marginBottom: 12, display: 'flex', alignItems: 'center', gap: 8 }}>
                {visible.length > 0 ? (
                    <span style={{ width: 8, height: 8, borderRadius: '50%', background: '#f59e0b', display: 'inline-block', animation: 'pulse 1.5s infinite' }} />
                ) : (
                    <span style={{ width: 8, height: 8, borderRadius: '50%', background: T.border, display: 'inline-block' }} />
                )}
                Active Node Migrations
                <span style={{ fontSize: 11, fontWeight: 500, color: T.textMuted }}>
                    ({visible.length} migration{visible.length !== 1 ? 's' : ''})
                </span>
            </div>

            <style>{`@keyframes pulse { 0%,100%{opacity:1} 50%{opacity:.4} }`}</style>

            {visible.length === 0 ? (
                <div style={{ background: T.surface, border: `1px dashed ${T.border}`, borderRadius: 10, padding: '32px 20px', textAlign: 'center', boxShadow: 'none' }}>
                    <div style={{ fontSize: 24, marginBottom: 8 }}>💤</div>
                    <div style={{ fontSize: 14, fontWeight: 600, color: T.textMid }}>No Active Migrations</div>
                    <div style={{ fontSize: 13, color: T.textMuted, marginTop: 4 }}>The cluster is currently stable and no nodes are being replaced.</div>
                </div>
            ) : (
                visible.map((action, ai) => {
                    const currentStepIdx = STEP_CURRENT_MAP[action.current_step] ?? -1;
                    const meta = action.action_metadata || {};
                    const isS2S = meta.spot_to_spot === true;
                    const s2sReason = meta.reason || null;
                    const isDiversify = s2sReason && s2sReason.startsWith('diversify');
                    const borderColor = isS2S ? '#f59e0b' : T.border;

                    return (
                    <div key={ai} style={{ background: T.surface, border: `1px solid ${action.status === 'failed' ? T.red : borderColor}`, borderRadius: 10, padding: '16px 20px', marginBottom: 12, boxShadow: T.shadow }}>
                            {/* Header */}
                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 16 }}>
                                <div style={{ flex: 1, minWidth: 0 }}>
                                    {/* Migration type badge */}
                                    <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 4 }}>
                                        {isS2S ? (
                                            <span style={{
                                                fontSize: 10, fontWeight: 700, padding: '2px 8px', borderRadius: 10,
                                                background: '#fef3c7', color: '#d97706', letterSpacing: '0.05em',
                                            }}>
                                                {isDiversify ? '🔀 SPOT→SPOT (Diversify)' : '⚡ SPOT→SPOT (Risk)'}
                                            </span>
                                        ) : (
                                            <span style={{
                                                fontSize: 10, fontWeight: 700, padding: '2px 8px', borderRadius: 10,
                                                background: T.primaryLight, color: T.primary, letterSpacing: '0.05em',
                                            }}>
                                                ↑ OD→SPOT
                                            </span>
                                        )}
                                    </div>
                                    <div style={{ fontSize: 13, fontWeight: 700, color: T.text }}>
                                        {action.source_pool} → {action.target_pool}
                                    </div>
                                    {action.actual_instance_type && action.target_pool && !action.target_pool.startsWith(action.actual_instance_type) && (
                                        <div style={{ fontSize: 11, color: T.amber, marginTop: 2 }}>
                                            Actual: {action.actual_instance_type}{action.actual_az ? `:${action.actual_az}` : ''}
                                        </div>
                                    )}
                                    <div style={{ fontSize: 11, color: T.textMuted, marginTop: 2 }}>
                                        {(meta.instance_id || action.instance_id) && (
                                            <span style={{ fontFamily: 'monospace', background: T.bg, padding: '1px 6px', borderRadius: 3, marginRight: 8 }}>
                                                {meta.instance_id || action.instance_id}
                                            </span>
                                        )}
                                        Started {action.started_at ? new Date(action.started_at).toLocaleTimeString() : '—'}
                                    </div>
                                    {/* S2S reason line */}
                                    {isS2S && s2sReason && (
                                        <div style={{ fontSize: 11, color: '#92400e', marginTop: 4, padding: '3px 8px', background: '#fef3c7', borderRadius: 4, display: 'inline-block', maxWidth: '100%', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}
                                            title={s2sReason}>
                                            {s2sReason}
                                        </div>
                                    )}
                                </div>
                                <span style={{
                                    fontSize: 11, fontWeight: 600, padding: '3px 10px', borderRadius: 12, flexShrink: 0, marginLeft: 8,
                                    background: action.status === 'completed' ? T.greenLight : action.status === 'failed' ? T.redLight : T.amberLight,
                                    color: action.status === 'completed' ? T.green : action.status === 'failed' ? T.red : T.amber,
                                }}>
                                    {action.status === 'waiting_agent' || action.status === 'in_progress' ? 'In Progress' : action.status.toUpperCase()}
                                </span>
                            </div>

                            {/* Step Timeline */}
                            <div style={{ display: 'flex', alignItems: 'flex-start', gap: 0, overflowX: 'auto', paddingBottom: 8 }}>
                                {REBALANCE_STEPS.map((step, si) => {
                                    const done = Boolean(action[step.key]);
                                    const active = !done && si === currentStepIdx;
                                    const pending = !done && !active;
                                    const verified = step.verifiedKey ? action[step.verifiedKey] : true;
                                    const doneUnverified = done && verified === false;

                                    const dotColor = done ? (doneUnverified ? T.amber : T.green) : active ? T.amber : T.greyBorder;
                                    const labelColor = done ? (doneUnverified ? T.amber : T.green) : active ? T.amber : T.textFaint;

                                    return (
                                        <div key={step.key} style={{ flex: 1, minWidth: 80, display: 'flex', flexDirection: 'column', alignItems: 'center', position: 'relative' }}>
                                            {/* Connector line (not for last step) */}
                                            {si < REBALANCE_STEPS.length - 1 && (
                                                <div style={{
                                                    position: 'absolute', top: 8, left: '50%', width: '100%', height: 2,
                                                    background: done ? (doneUnverified ? T.amber : T.green) : T.greyBorder, zIndex: 0
                                                }} />
                                            )}
                                            {/* Dot */}
                                            <div style={{
                                                width: 18, height: 18, borderRadius: '50%',
                                                background: done ? (doneUnverified ? T.amber : T.green) : active ? T.amber : T.surface,
                                                border: `2px solid ${dotColor}`,
                                                display: 'flex', alignItems: 'center', justifyContent: 'center',
                                                zIndex: 1, position: 'relative',
                                                animation: active ? 'pulse 1.5s infinite' : 'none',
                                            }}>
                                                {done && !doneUnverified && <span style={{ color: '#fff', fontSize: 10, fontWeight: 900 }}>✓</span>}
                                                {doneUnverified && <span style={{ color: '#fff', fontSize: 10, fontWeight: 900 }}>!</span>}
                                            </div>
                                            {/* Label */}
                                            <div style={{ fontSize: 10, fontWeight: 600, color: labelColor, textAlign: 'center', marginTop: 6, lineHeight: 1.3, maxWidth: 80 }}>
                                                {step.label}
                                            </div>
                                            {/* Verification badge */}
                                            {done && step.verifiedKey && (
                                                <div style={{ fontSize: 8, fontWeight: 700, textAlign: 'center', marginTop: 1, color: verified ? T.green : T.amber }}>
                                                    {verified ? 'Verified' : 'Unverified'}
                                                </div>
                                            )}
                                            {/* Timestamp if done */}
                                            {done && action[step.key] && (
                                                <div style={{ fontSize: 9, color: T.textFaint, textAlign: 'center', marginTop: 2 }}>
                                                    {new Date(action[step.key]).toLocaleTimeString()}
                                                </div>
                                            )}
                                            {active && (
                                                <div style={{ fontSize: 9, color: T.amber, textAlign: 'center', marginTop: 2, fontWeight: 700 }}>
                                                    In progress...
                                                </div>
                                            )}
                                        </div>
                                    );
                                })}
                            </div>

                            {/* Waiting for spot node warning text */}
                            {action.current_step === 'waiting_for_spot_node' && (
                                <div style={{ marginTop: 12, padding: '8px 12px', background: T.amberLight, borderRadius: 6, fontSize: 12, color: T.amber, fontWeight: 500 }}>
                                    ⏳ Waiting for {action.provisioner_type === 'karpenter' ? 'Karpenter' : 'agent'} to provision a new spot node ({Math.round((action.spot_wait_elapsed_s || 0) / 60)} min elapsed, max 30 min)
                                </div>
                            )}
                            {/* Failed migration: show error + pool change trail */}
                            {action.status === 'failed' && action.error_message && (
                                <div style={{ marginTop: 12, padding: '8px 12px', background: T.redLight, borderRadius: 6, fontSize: 12, color: T.red, fontWeight: 500 }}>
                                    ✗ {action.error_message}
                                </div>
                            )}
                            {action.pool_change_reason && (
                                <div style={{ marginTop: 8, padding: '6px 10px', background: '#eff6ff', borderRadius: 6, fontSize: 11, color: '#1d4ed8', fontWeight: 500 }}>
                                    ℹ Pool change: {action.pool_change_reason}
                                </div>
                            )}
                            {action.status === 'completed' && action.realized_savings_mo > 0 && (
                                <div style={{ marginTop: 8, padding: '6px 10px', background: T.greenLight, border: `1px solid ${T.greenBorder}`, borderRadius: 6, fontSize: 11, color: T.green, fontWeight: 600, display: 'inline-block' }}>
                                    💰 Saving ${action.realized_savings_mo.toFixed(2)}/mo (${action.realized_savings_hr.toFixed(4)}/hr)
                                </div>
                            )}
                    </div>
                    );
                })
            )}
        </div>
    );
};

export default RebalancingTimeline;
